#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string s;
    cin >> s;
    int winCount = 0, maxLength = 0;
    int startIdx = 0, endIdx = 0;

    // Replace all "__" with "_"
    while (s.find("__") != string::npos) {
        size_t pos = s.find("__");
        s.replace(pos, 2, "_");
    }
    n = (int)s.length();

    // Process the first segment if it starts with '('
    if (startIdx < n && s[startIdx] == '(') {
        endIdx = startIdx;
        while (endIdx < n && s[endIdx] != ')') endIdx++;
        if (endIdx < n && s[endIdx] == ')') {
            string temp = s.substr(startIdx + 1, endIdx - startIdx - 1);
            if (temp.find('_') == string::npos && (int)temp.length() > 0)
                winCount++;
            else {
                int tokens = 1;
                for (char c : temp) {
                    if (c == '_') tokens++;
                }
                winCount += tokens;
            }
            startIdx = endIdx + 1;
        }
    }

    // Process remaining segments within parentheses
    for (int i = 0; i < n; i++) {
        if (s[i] == '(') {
            int j = i;
            while (j < n && s[j] != ')') j++;
            if (j < n && s[j] == ')') {
                string temp = s.substr(i + 1, j - i - 1);
                if (temp.find('_') == string::npos && (int)temp.length() > 0)
                    winCount++;
                else {
                    int tokens = 1;
                    for (char c : temp) {
                        if (c == '_') tokens++;
                    }
                    winCount += tokens;
                }
                i = j;
            }
        }
    }

    // Replace all parentheses with underscores
    while (s.find('(') != string::npos || s.find(')') != string::npos) {
        size_t pos1 = s.find('(');
        size_t pos2 = s.find(')');
        while (pos1 != string::npos || pos2 != string::npos) {
            if (pos1 != string::npos && (pos2 == string::npos || pos1 < pos2)) {
                s[pos1] = '_';
                pos1 = s.find('(');
            } else if (pos2 != string::npos) {
                s[pos2] = '_';
                pos2 = s.find(')');
            } else {
                break;
            }
        }
    }

    // Split the string by '_'
    stringstream ss(s);
    string part;
    while (getline(ss, part, '_')) {
        if ((int)part.length() > maxLength)
            maxLength = part.length();
    }

    cout << maxLength << " " << winCount << "\n";

    return 0;
}
